/** ReplicatedStorage.Shared.ShurikenEffects: plays the game's effects (timelines, projectiles, lightning, telegraphs, flashes, shake, hit-stop) on the clients. Generated Luau (keep it passing tests/runtime-lint.test.ts). */
export const FX_RUNTIME_MODULE_VERSION = 4;

export const FX_RUNTIME_MODULE = `--!strict
-- ShurikenEffects v4 (generated by Shuriken Studio; safe to use, don't edit).
-- Plays the game's effects by name (templates in ReplicatedStorage.ShurikenEffects, built from
-- effects/*.fx.json). An effect is a timeline: particles, shells (spheres, domes, discs, pillars), rings,
-- slashes, ribbons along paths, beams and lightning, lights, sounds, camera shake, hit-stop, highlights,
-- debris, ground decals and screen FX, each at its own time with its own curves.
--   local Effects = require(game.ReplicatedStorage.Shared.ShurikenEffects)
--   Effects.play("FireballImpact", hitCFrame)             -- Vector3, CFrame, part, attachment or model
--   local aura = Effects.attach("Aura", root)              -- persistent: aura.stop() later
--   local trail = Effects.trail("SlashTrail", blade)       -- trail.Enabled = true while swinging
--   Effects.beam("EnergyBeam", attachmentA, attachmentB)
--   Effects.projectile({ from = hand, to = target, speed = 90, body = "FireBolt", impact = "FireballImpact" })
--   Effects.lightning(fromPos, toPos, { color = Color3.fromRGB(150, 200, 255) })
--   Effects.telegraph(groundCFrame, { radius = 12, seconds = 1.2 })  -- warning circle that fills, then hits
--   Effects.flash(model)  Effects.shake(1.5, 0.25, player)  Effects.hitStop(character, 0.06)
-- Called on the server, every call is relayed to the clients as ONE remote message (particles and cameras
-- are client-side); opts.players / opts.except (the attacker who already played it) / opts.radius (only
-- players within that many studs) choose who gets it. Clients play within a budget per quality level
-- (Effects.quality(): the player's graphics setting, or Effects.setQuality from a settings menu), skip
-- far and off-screen effects, pool their parts and clean up after themselves. Idle, nothing runs.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local TweenService = game:GetService("TweenService")
local GuiService = game:GetService("GuiService")
local ContentProvider = game:GetService("ContentProvider")
local Curves = require(script.Parent.ShurikenCurves)

export type Options = {
	color: Color3?, -- tints every part of the effect
	scale: number?, -- size multiplier (speeds too)
	count: number?, -- particle-count multiplier
	follow: boolean?, -- stay on the part/attachment it was played on
	target: Instance?, -- the model hit: highlight and hit-stop tracks act on it
	to: Vector3?, -- where beam tracks with to = "target" end
	force: boolean?, -- play even when far, off-screen or over budget (cutscenes, a boss's ultimate)
	players: { Player }?, -- server: only these players
	except: Player?, -- server: everyone but this player (who already played it locally)
	radius: number?, -- server: only players within this many studs of it
	seconds: number?, -- server: how long a persistent effect runs on the clients (default 5)
}
export type Handle = {
	attachment: Attachment, -- where it plays (its emitters' main attachment)
	stop: () -> (), -- emitters off, loops end; what is in the air finishes
	destroy: () -> (), -- gone now
	alive: () -> boolean,
	move: (at: CFrame) -> (), -- carry it somewhere (a projectile's body)
}
export type Quality = "low" | "medium" | "high"
export type Budget = { particles: number, effects: number, lights: number, distance: number, rank: number }

local Effects = {}

local warned: { [string]: boolean } = {}
local function warnOnce(key: string, message: string)
	if not warned[key] then
		warned[key] = true
		warn("[ShurikenEffects] " .. message)
	end
end

local function relaying(): boolean
	return RunService:IsServer() and RunService:IsRunning() and not RunService:IsClient()
end

local function rootFolder(): Instance?
	local r = ReplicatedStorage:FindFirstChild("ShurikenEffects")
	if r or not relaying() then
		return r
	end
	-- A place with no effect built yet: the server makes the folder and its remote.
	local made = Instance.new("Folder")
	made.Name = "ShurikenEffects"
	local remote = Instance.new("RemoteEvent")
	remote.Name = "Remote"
	remote.Parent = made
	made.Parent = ReplicatedStorage
	return made
end

local function remoteEvent(): RemoteEvent?
	local r = rootFolder()
	local e = r and r:FindFirstChild("Remote")
	return if e and e:IsA("RemoteEvent") then e else nil
end

local function template(name: string): Instance?
	local r = rootFolder()
	local t = r and r:FindFirstChild(name)
	if not t then
		warnOnce("missing:" .. name, ("no effect named %s (build it with vfx_create)"):format(name))
	end
	return t
end

local function num(v: any, default: number): number
	return if typeof(v) == "number" then v else default
end

local function vec(v: any, default: Vector3): Vector3
	if typeof(v) == "Vector3" then
		return v
	elseif typeof(v) == "table" and typeof(v[1]) == "number" then
		return Vector3.new(v[1], num(v[2], 0), num(v[3], 0))
	end
	return default
end

local hexCache: { [string]: Color3 } = {}
local function hex(v: any, default: Color3?): Color3
	if typeof(v) == "Color3" then
		return v
	elseif typeof(v) ~= "string" then
		return default or Color3.new(1, 1, 1)
	end
	local c = hexCache[v]
	if not c then
		local ok, made = pcall(Color3.fromHex, v)
		c = if ok then made else (default or Color3.new(1, 1, 1))
		hexCache[v] = c
	end
	return c
end

local function enumItem(enum: any, name: any, default: any): any
	if typeof(name) ~= "string" then
		return default
	end
	local ok, item = pcall(function()
		return enum[name]
	end)
	return if ok and typeof(item) == "EnumItem" then item else default
end

-- Lazily required sibling modules (games that never use them don't need them).
local loaded: { [string]: any } = {}
local function sibling(name: string): any
	local got = loaded[name]
	if got ~= nil then
		return if got == false then nil else got
	end
	local m = script.Parent and script.Parent:FindFirstChild(name)
	if m and m:IsA("ModuleScript") then
		local ok, mod = pcall(require, m)
		if ok then
			loaded[name] = mod
			return mod
		end
		warnOnce("require:" .. name, ("couldn't load %s: %s"):format(name, tostring(mod)))
	end
	loaded[name] = false
	return nil
end

------------------------------------------------------------------------------------------- Quality and budgets
local BUDGETS: { [Quality]: Budget } = {
	low = { particles = 0.35, effects = 10, lights = 2, distance = 160, rank = 1 },
	medium = { particles = 0.7, effects = 24, lights = 4, distance = 260, rank = 2 },
	high = { particles = 1, effects = 40, lights = 8, distance = 400, rank = 3 },
}
local RANK: { [string]: number } = { low = 1, medium = 2, high = 3 }
local qualityOverride: Quality? = nil
local frameTime = 1 / 50 -- measured while effects run (for the Automatic graphics setting)

--- "low", "medium" or "high": the game's choice (Effects.setQuality), else the player's graphics level
--- (1-3 low, 4-7 medium, 8-10 high), else (Automatic) by the frame rate measured while effects play.
function Effects.quality(): Quality
	if qualityOverride then
		return qualityOverride
	end
	local ok, level = pcall(function()
		return UserSettings():GetService("UserGameSettings").SavedQualityLevel
	end)
	if ok and level ~= Enum.SavedQualitySetting.Automatic then
		local v = level.Value
		return if v <= 3 then "low" elseif v <= 7 then "medium" else "high"
	end
	return if frameTime > 1 / 40 then "low" elseif frameTime < 1 / 57 then "high" else "medium"
end

--- The game's own effects-quality setting (a settings menu); nil follows the player's graphics level.
function Effects.setQuality(level: Quality?)
	qualityOverride = level
end

--- What the current quality level allows: particle multiplier, effects at once, lights, culling distance.
function Effects.budget(): Budget
	return BUDGETS[Effects.quality()]
end

------------------------------------------------------------------------------------------- Containers and pools
local container: Folder? = nil
local function fxFolder(): Folder
	local c = container
	if c and c.Parent then
		return c
	end
	local f = Instance.new("Folder")
	f.Name = "ShurikenFX"
	if not RunService:IsRunning() then
		f:SetAttribute("ShurikenEffectPreview", true) -- an Edit-mode preview: cleanup scripts find it
	end
	f.Parent = workspace
	container = f
	return f
end

local partPool: { [string]: { BasePart } } = {}
local partsOut = 0

local function newPart(kind: string): BasePart
	local p: BasePart
	if kind == "wedge" then
		p = Instance.new("WedgePart")
	else
		local part = Instance.new("Part")
		part.Shape = if kind == "sphere" then Enum.PartType.Ball elseif kind == "cylinder" then Enum.PartType.Cylinder else Enum.PartType.Block
		p = part
	end
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.CastShadow = false
	p.Massless = true
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Name = "FX"
	p:SetAttribute("PoolKind", kind)
	return p
end

local function takePart(kind: string): BasePart
	local pool = partPool[kind]
	local p = if pool then table.remove(pool) else nil
	local part = p or newPart(kind)
	part.Transparency = 1
	part.Material = Enum.Material.SmoothPlastic
	part.Color = Color3.new(1, 1, 1)
	part.Reflectance = 0
	part.Parent = fxFolder()
	partsOut += 1
	return part
end

local function givePart(p: BasePart)
	partsOut -= 1
	for _, c in p:GetChildren() do
		c:Destroy()
	end
	local kind = p:GetAttribute("PoolKind")
	local pool = if typeof(kind) == "string" then (partPool[kind] or {}) else nil
	if not pool or #pool >= 48 then
		p:Destroy()
		return
	end
	partPool[kind :: string] = pool
	p.Parent = nil
	table.insert(pool, p)
end

local attachmentPool: { Attachment } = {}
local function takeAttachment(at: CFrame?): Attachment
	local a = table.remove(attachmentPool) or Instance.new("Attachment")
	a.Name = "ShurikenEffect"
	a.Parent = workspace.Terrain
	if at then
		a.WorldCFrame = at
	end
	return a
end

local function giveAttachment(a: Attachment)
	for _, c in a:GetChildren() do
		c:Destroy()
	end
	if #attachmentPool >= 96 then
		a:Destroy()
		return
	end
	a.Parent = nil
	table.insert(attachmentPool, a)
end

------------------------------------------------------------------------------------------- The frame step
-- One Heartbeat connection runs every live effect; it exists only while something plays.
type Job = (dt: number, now: number) -> boolean -- false when finished
local jobs: { Job } = {}
local stepper: RBXScriptConnection? = nil
local live: { { count: number, untilAt: number } } = {} -- particle batches still alive (for stats)
local effectsLive = 0
local lightsLive = 0
local highlightsLive = 0

local function step(dt: number)
	frameTime = frameTime * 0.95 + math.min(dt, 0.25) * 0.05
	local now = os.clock()
	local i = 1
	while i <= #jobs do
		local ok, alive = pcall(jobs[i], dt, now)
		if ok and alive then
			i += 1
		else
			if not ok then
				warnOnce("job:" .. tostring(alive), tostring(alive))
			end
			jobs[i] = jobs[#jobs]
			jobs[#jobs] = nil
		end
	end
	for j = #live, 1, -1 do
		if live[j].untilAt < now then
			table.remove(live, j)
		end
	end
	local connection = stepper
	if #jobs == 0 and connection then
		connection:Disconnect()
		stepper = nil
	end
end

local function run(job: Job)
	table.insert(jobs, job)
	if not stepper then
		stepper = RunService.Heartbeat:Connect(step)
	end
end

local function noteParticles(count: number, lifetime: number)
	table.insert(live, { count = count, untilAt = os.clock() + lifetime })
	if not stepper then
		run(function(_: number, now: number): boolean
			return #live > 0 and live[#live].untilAt >= now
		end)
	end
end

------------------------------------------------------------------------------------------- Where things play
local function cframeOf(where: any): CFrame?
	local kind = typeof(where)
	if kind == "CFrame" then
		return where
	elseif kind == "Vector3" then
		return CFrame.new(where)
	elseif kind == "Instance" then
		if where:IsA("Attachment") then
			return where.WorldCFrame
		elseif where:IsA("BasePart") then
			return where.CFrame
		elseif where:IsA("Model") then
			return where:GetPivot()
		end
	end
	return nil
end

-- The part or attachment an effect follows when opts.follow is set.
local function anchorOf(where: any): Instance?
	if typeof(where) == "Instance" then
		if where:IsA("Attachment") or where:IsA("BasePart") then
			return where
		elseif where:IsA("Model") then
			return where.PrimaryPart or where:FindFirstChildWhichIsA("BasePart")
		end
	end
	return nil
end

local function camera(): Camera?
	return workspace.CurrentCamera
end

--- Whether an effect at \`position\` (about \`radius\` studs across) is worth drawing for this client.
local function worthPlaying(position: Vector3, radius: number, force: boolean?): boolean
	if force or not RunService:IsRunning() then
		return true
	end
	local cam = camera()
	if not cam then
		return true
	end
	local budget = Effects.budget()
	local offset = position - cam.CFrame.Position
	local distance = offset.Magnitude
	if distance > budget.distance + radius then
		return false
	end
	-- Behind the camera and not close: a burst is over before the player could turn around.
	if distance > 25 + radius and cam.CFrame.LookVector:Dot(offset) < -radius then
		return false
	end
	if effectsLive >= budget.effects and distance > 40 then
		return false
	end
	return true
end

------------------------------------------------------------------------------------------- Camera shake
local shakes: { { magnitude: number, start: number, duration: number } } = {}
local shaking = false
local shakeScale = 1

local function reducedMotion(): boolean
	local Motion = sibling("Motion")
	if Motion and Motion.reduced then
		local ok, reduced = pcall(Motion.reduced)
		if ok then
			return reduced == true
		end
	end
	local ok, reduced = pcall(function()
		return GuiService.ReducedMotionEnabled
	end)
	return ok and reduced == true
end

local function shakeCamera(magnitude: number, duration: number)
	if shakeScale <= 0 or reducedMotion() then
		return -- Reduce Motion: no shake at all
	end
	table.insert(shakes, { magnitude = magnitude * shakeScale, start = os.clock(), duration = math.max(duration, 0.01) })
	if shaking then
		return
	end
	shaking = true
	-- After the camera scripts: they set the camera every frame, so the offset never accumulates.
	RunService:BindToRenderStep("ShurikenShake", Enum.RenderPriority.Camera.Value + 1, function()
		local now = os.clock()
		local amount = 0
		for i = #shakes, 1, -1 do
			local s = shakes[i]
			local left = 1 - (now - s.start) / s.duration
			if left <= 0 then
				table.remove(shakes, i)
			else
				amount += s.magnitude * left * left
			end
		end
		local cam = camera()
		if amount <= 0 or not cam then
			RunService:UnbindFromRenderStep("ShurikenShake")
			shaking = false
			return
		end
		local t = now * 30
		local pitch = math.noise(t, 0.5) * amount * 2
		local yaw = math.noise(0.5, t) * amount * 2
		local roll = math.noise(t, 3.3) * amount
		cam.CFrame = cam.CFrame * CFrame.Angles(math.rad(pitch), math.rad(yaw), math.rad(roll))
	end)
end

--- A multiplier for every camera shake (a settings slider): 0 turns shake off. Reduce Motion always does.
function Effects.setShake(scale: number)
	shakeScale = math.max(0, scale)
end

------------------------------------------------------------------------------------------- Relay (server -> clients)
local function positionOf(where: any): Vector3?
	local cf = cframeOf(where)
	return if cf then cf.Position else nil
end

local function relay(cue: string, a: any, b: any, opts: any)
	local remote = remoteEvent()
	if not remote then
		return
	end
	local o = if typeof(opts) == "table" then opts else nil
	if not (o and (o.players or o.except or o.radius)) then
		remote:FireAllClients(cue, a, b, o)
		return
	end
	local clean = table.clone(o)
	clean.players, clean.except, clean.radius = nil, nil, nil
	local targets = o.players or Players:GetPlayers()
	local at = positionOf(a)
	for _, player in targets do
		if player == o.except then
			continue
		end
		if o.radius and at then
			local character = player.Character
			local root = character and character.PrimaryPart
			if root and (root.Position - at).Magnitude > o.radius then
				continue
			end
		end
		remote:FireClient(player, cue, a, b, clean)
	end
end

------------------------------------------------------------------------------------------- Emitters
local rng = Random.new()

local function scaledSequence(seq: NumberSequence, k: number): NumberSequence
	if k == 1 then
		return seq
	end
	local out = {}
	for _, p in seq.Keypoints do
		table.insert(out, NumberSequenceKeypoint.new(p.Time, p.Value * k, p.Envelope * k))
	end
	return NumberSequence.new(out)
end

-- Template values -> a live emitter, with the play's colour and scale.
local function dress(e: ParticleEmitter, tpl: ParticleEmitter, opts: Options?)
	local k = if opts and opts.scale then opts.scale else 1
	e.Color = if opts and opts.color then ColorSequence.new(opts.color) else tpl.Color
	e.Size = scaledSequence(tpl.Size, k)
	e.Speed = NumberRange.new(tpl.Speed.Min * k, tpl.Speed.Max * k)
	e.Acceleration = tpl.Acceleration * k
end

-- A template's emitters, cloned once and reused: emitters with an Offset or Turn sit on their own
-- attachment at that place relative to the main one (a slash tilted 30°, sparks at the blade's tip).
type Host = {
	attachment: Attachment,
	extras: { { attachment: Attachment, offset: CFrame } },
	emitters: { { live: ParticleEmitter, tpl: ParticleEmitter } },
	freeAt: number,
}
local hostPools: { [Instance]: { Host } } = {}

local function emittersOf(tpl: Instance): { ParticleEmitter }
	local out = {}
	for _, c in tpl:GetChildren() do
		if c:IsA("ParticleEmitter") then
			table.insert(out, c)
		end
	end
	return out
end

local function placeHost(host: Host, at: CFrame)
	host.attachment.WorldCFrame = at
	for _, x in host.extras do
		x.attachment.WorldCFrame = at * x.offset
	end
end

local function hostParent(host: Host, parent: Instance?)
	host.attachment.Parent = parent
	for _, x in host.extras do
		x.attachment.Parent = parent
	end
end

local function takeHost(tpl: Instance, at: CFrame, parent: Instance?): Host
	local pool = hostPools[tpl]
	if not pool then
		pool = {}
		hostPools[tpl] = pool
	end
	local now = os.clock()
	if not parent then
		for _, h in pool do
			if h.freeAt <= now and h.attachment.Parent == nil then
				hostParent(h, workspace.Terrain)
				placeHost(h, at)
				h.freeAt = math.huge
				return h
			end
		end
	end
	local a = Instance.new("Attachment")
	a.Name = "ShurikenEffect"
	local host: Host = { attachment = a, extras = {}, emitters = {}, freeAt = math.huge }
	local byPlace: { [string]: Attachment } = {}
	for _, e in emittersOf(tpl) do
		local offset = e:GetAttribute("Offset")
		local turnBy = e:GetAttribute("Turn")
		local holder = a
		if typeof(offset) == "Vector3" or typeof(turnBy) == "Vector3" then
			local o = if typeof(offset) == "Vector3" then offset else Vector3.zero
			local r = if typeof(turnBy) == "Vector3" then turnBy else Vector3.zero
			local key = tostring(o) .. "|" .. tostring(r)
			local extra = byPlace[key]
			if not extra then
				local made = Instance.new("Attachment")
				made.Name = "ShurikenEffectPart"
				byPlace[key] = made
				table.insert(host.extras, { attachment = made, offset = CFrame.new(o) * CFrame.Angles(math.rad(r.X), math.rad(r.Y), math.rad(r.Z)) })
				extra = made
			end
			holder = extra
		end
		local copy = e:Clone()
		copy.Enabled = false
		copy.Parent = holder
		table.insert(host.emitters, { live = copy, tpl = e })
	end
	hostParent(host, parent or workspace.Terrain)
	placeHost(host, at)
	if not parent and #pool < 6 then
		table.insert(pool, host)
	end
	return host
end

local function releaseHost(host: Host, after: number)
	host.freeAt = os.clock() + after
	task.delay(after, function()
		if host.attachment.Parent == workspace.Terrain then
			hostParent(host, nil) -- pooled: back to the pool (or collected when it wasn't pooled)
		end
	end)
end

-- Emits every burst emitter of a host at its delay; returns how long until the last particle is gone.
local function emitAll(host: Host, opts: Options?, persistent: boolean): number
	local budget = Effects.budget()
	local countScale = (if opts and opts.count then opts.count else 1) * budget.particles
	local longest = 0
	for _, pair in host.emitters do
		local e, tpl = pair.live, pair.tpl
		dress(e, tpl, opts)
		local detail = tpl:GetAttribute("Detail")
		if typeof(detail) == "string" and (RANK[detail] or 1) > budget.rank then
			e.Enabled = false
			continue
		end
		if persistent then
			e.Rate = tpl.Rate * countScale
			e.Enabled = true
			continue
		end
		local n = math.max(1, math.round(num(tpl:GetAttribute("EmitCount"), 10) * countScale))
		local delay = num(tpl:GetAttribute("EmitDelay"), 0)
		local emitFor = num(tpl:GetAttribute("EmitFor"), 0)
		local lifetime = tpl.Lifetime.Max
		longest = math.max(longest, delay + emitFor + lifetime)
		local function go()
			if not e.Parent then
				return
			end
			if emitFor > 0 then
				e.Rate = tpl.Rate * countScale
				e.Enabled = true
				noteParticles(math.round(e.Rate * emitFor), emitFor + lifetime)
				task.delay(emitFor, function()
					e.Enabled = false
				end)
			else
				e:Emit(n)
				noteParticles(n, lifetime)
			end
		end
		if delay > 0 then
			task.delay(delay, go)
		else
			go()
		end
	end
	return longest
end

------------------------------------------------------------------------------------------- Timelines
local timelines: { [Instance]: { any } } = {}

local function timelineOf(tpl: Instance): { any }
	local cached = timelines[tpl]
	if cached then
		return cached
	end
	local out = {}
	local v = tpl:FindFirstChild("Timeline")
	if v and v:IsA("StringValue") then
		local ok, decoded = pcall(function()
			return HttpService:JSONDecode(v.Value)
		end)
		if ok and typeof(decoded) == "table" then
			out = decoded
		else
			warnOnce("timeline:" .. tpl.Name, tpl.Name .. ": its timeline couldn't be read")
		end
	end
	table.sort(out, function(a, b)
		return num(a.at, 0) < num(b.at, 0)
	end)
	timelines[tpl] = out
	tpl.Destroying:Once(function()
		timelines[tpl] = nil
	end)
	return out
end

type Ctx = {
	base: () -> CFrame, -- where the effect is now (it may follow a part)
	opts: Options,
	scale: number,
	tint: Color3?,
	target: Instance?,
	persistent: boolean,
}
type Runner = (track: any, ctx: Ctx) -> (((t: number, dt: number) -> boolean)?, (() -> ())?)

local function localCFrame(track: any, scale: number): CFrame
	local o = vec(track.offset, Vector3.zero) * scale
	local r = vec(track.rotation, Vector3.zero)
	return CFrame.new(o) * CFrame.Angles(math.rad(r.X), math.rad(r.Y), math.rad(r.Z))
end

local function tinted(ctx: Ctx, c: Color3): Color3
	local t = ctx.tint
	return if t then Color3.new(c.R * t.R, c.G * t.G, c.B * t.B) else c
end

-- Progress through a track: 0..1 over its duration (looping tracks of persistent effects wrap).
local function progress(track: any, ctx: Ctx, t: number): (number, boolean)
	local duration = math.max(num(track.duration, 0.3), 1e-3)
	if ctx.persistent and track.loop then
		return (t % duration) / duration, true
	end
	return math.clamp(t / duration, 0, 1), t < duration
end

local function groundBelow(position: Vector3, depth: number): RaycastResult?
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = { fxFolder() }
	params.IgnoreWater = false
	return workspace:Raycast(position + Vector3.new(0, 2, 0), Vector3.new(0, -depth, 0), params)
end

local RUNNERS: { [string]: Runner } = {}

-- A part that grows, fades and changes colour: flash spheres, domes, discs, pillars, shields, custom meshes.
RUNNERS.shell = function(track: any, ctx: Ctx)
	local shape = if typeof(track.shape) == "string" then track.shape else "sphere"
	local kind = if shape == "sphere" or shape == "dome" then "sphere" elseif shape == "cylinder" or shape == "disc" or shape == "pillar" then "cylinder" elseif shape == "wedge" then "wedge" else "block"
	local p = takePart(kind)
	p.Material = enumItem(Enum.Material, track.material, Enum.Material.Neon)
	local mesh: SpecialMesh? = nil
	if shape == "mesh" and typeof(track.meshId) == "string" then
		local m = Instance.new("SpecialMesh")
		m.MeshType = Enum.MeshType.FileMesh
		m.MeshId = track.meshId
		m.TextureId = if typeof(track.textureId) == "string" then track.textureId else ""
		m.Parent = p
		mesh = m
	end
	local base = vec(track.size, Vector3.new(4, 4, 4)) * ctx.scale
	-- A Cylinder part's length is its X axis: discs and pillars stand it up.
	local turn = if kind == "cylinder" then CFrame.Angles(0, 0, math.rad(90)) else CFrame.identity
	local offset = localCFrame(track, ctx.scale) * turn
	local spin = vec(track.spin, Vector3.zero)
	local scaleCurve = track.scale or 1
	local fade = track.transparency or { 0, 1 }
	local color = track.color or "#ffffff"
	local function update(t: number, _: number): boolean
		local k, going = progress(track, ctx, t)
		local s = math.max(Curves.sample(scaleCurve, k), 0)
		local size = base * s
		if kind == "cylinder" then
			size = Vector3.new(size.Y, size.X, size.Z)
		end
		size = size:Max(Vector3.new(0.05, 0.05, 0.05))
		if mesh then
			p.Size = Vector3.new(1, 1, 1)
			mesh.Scale = size
		else
			p.Size = size
		end
		p.Transparency = math.clamp(Curves.sample(fade, k), 0, 1)
		p.Color = tinted(ctx, Curves.sampleColor(color, k))
		local turned = CFrame.Angles(math.rad(spin.X * t), math.rad(spin.Y * t), math.rad(spin.Z * t))
		p.CFrame = ctx.base() * offset * turned
		return going
	end
	return update, function()
		givePart(p)
	end
end

local function lightOf(track: any, a: Attachment): (Light, (number) -> ())
	if track.kind == "spot" then
		local spot = Instance.new("SpotLight")
		spot.Angle = num(track.angle, 60)
		spot.Face = Enum.NormalId.Front
		spot.Shadows = track.shadows == true
		spot.Parent = a
		return spot, function(range: number)
			spot.Range = range
		end
	end
	local point = Instance.new("PointLight")
	point.Shadows = track.shadows == true
	point.Parent = a
	return point, function(range: number)
		point.Range = range
	end
end

-- A light flash or glow: brightness and range over the track, an optional flicker.
RUNNERS.light = function(track: any, ctx: Ctx)
	if lightsLive >= Effects.budget().lights and not ctx.opts.force then
		return nil, nil
	end
	lightsLive += 1
	local a = takeAttachment(ctx.base())
	local l, setRange = lightOf(track, a)
	l.Color = tinted(ctx, hex(track.color, Color3.new(1, 0.8, 0.5)))
	local offset = localCFrame(track, ctx.scale)
	local flicker = num(track.flicker, 0)
	local seed = rng:NextNumber(0, 100)
	local function update(t: number, _: number): boolean
		local k, going = progress(track, ctx, t)
		local f = if flicker > 0 then 1 - flicker + flicker * Curves.flicker(t, seed) else 1
		l.Brightness = math.max(Curves.sample(track.brightness or { 4, 0 }, k), 0) * f
		setRange(math.clamp(Curves.sample(track.range or 12, k) * ctx.scale, 0, 60))
		a.WorldCFrame = ctx.base() * offset
		return going
	end
	return update, function()
		lightsLive -= 1
		giveAttachment(a)
	end
end

local function beamFrom(track: any, ctx: Ctx): Beam
	local b = Instance.new("Beam")
	b.Color = if ctx.tint then ColorSequence.new(tinted(ctx, Curves.sampleColor(track.color or "#ffffff", 0.5))) else Curves.colorSequence(track.color or "#ffffff")
	b.LightEmission = num(track.lightEmission, 1)
	b.LightInfluence = num(track.lightInfluence, 0)
	pcall(function()
		b.Brightness = num(track.brightness, 1)
	end)
	b.FaceCamera = track.faceCamera ~= false
	b.Segments = math.clamp(math.floor(num(track.segments, 10)), 1, 1000)
	b.ZOffset = num(track.zOffset, 0)
	if typeof(track.texture) == "string" and track.texture ~= "" then
		b.Texture = track.texture
		b.TextureSpeed = num(track.textureSpeed, 0)
		b.TextureLength = num(track.textureLength, 1)
		b.TextureMode = enumItem(Enum.TextureMode, track.textureMode, Enum.TextureMode.Stretch)
	end
	return b
end

-- A beam (or a crackling chain of them): lasers, tethers, lightning, light shafts.
RUNNERS.beam = function(track: any, ctx: Ctx)
	local from = vec(track.from, Vector3.zero) * ctx.scale
	local toTarget = track.to == "target"
	local to = vec(track.to, Vector3.new(0, 0, -10)) * ctx.scale
	local jag = track.jag
	local count = if typeof(jag) == "table" then math.clamp(math.floor(num(jag.segments, 8)), 2, 24) else 1
	local points: { Attachment } = {}
	for _ = 0, count do
		table.insert(points, takeAttachment())
	end
	local beams: { Beam } = {}
	local widths = vec(track.width, Vector3.new(0.5, 0.5, 0))
	local alongCurve = track.transparency or 0
	for i = 1, count do
		local b = beamFrom(track, ctx)
		b.Attachment0 = points[i]
		b.Attachment1 = points[i + 1]

		b.Parent = points[i]
		table.insert(beams, b)
	end
	local rate = if typeof(jag) == "table" then num(jag.rate, 15) else 0
	local amplitude = if typeof(jag) == "table" then num(jag.amplitude, 0.12) else 0
	local bend = vec(track.bend, Vector3.zero) * ctx.scale
	local nextJag = 0
	local seed = rng:NextInteger(1, 1e6)
	local lastFade = -1
	local function update(t: number, _: number): boolean
		local k, going = progress(track, ctx, t)
		local base = ctx.base()
		local a = base * from
		local b = if toTarget and ctx.opts.to then ctx.opts.to else (base * to)
		if count == 1 then
			-- Beam control points: Attachment0 + its X axis * CurveSize0, Attachment1 - its X axis * CurveSize1.
			-- Each attachment's X axis aims at its control point: a third along the beam, bent by \`bend\`.
			local frame = CFrame.lookAt(a, b + Vector3.new(0, 1e-4, 0))
			local push = frame.RightVector * bend.X + frame.UpVector * bend.Y
			local third = (b - a) / 3
			local c0, c1 = third + push, third - push
			local function aim(at: Vector3, axis: Vector3): CFrame
				if axis.Magnitude < 1e-6 then
					return CFrame.new(at)
				end
				local x = axis.Unit
				local y = frame.UpVector - x * frame.UpVector:Dot(x)
				if y.Magnitude < 1e-3 then
					y = frame.RightVector - x * frame.RightVector:Dot(x)
				end
				return CFrame.fromMatrix(at, x, y.Unit)
			end
			points[1].WorldCFrame = aim(a, c0)
			points[2].WorldCFrame = aim(b, c1)
			beams[1].CurveSize0 = c0.Magnitude
			beams[1].CurveSize1 = c1.Magnitude
		elseif t >= nextJag then
			nextJag = t + (if rate > 0 then 1 / rate else math.huge)
			seed += 1
			local pts = Curves.lightning(a, b, { segments = count, amplitude = amplitude, seed = seed })
			for i, p in pts do
				points[i].WorldPosition = p
			end
		end
		local w = Curves.sample(track.widthScale or 1, k) * ctx.scale
		local fade = Curves.sample(track.fade or 0, k)
		for _, beam in beams do
			beam.Width0 = widths.X * w
			beam.Width1 = widths.Y * w
		end
		local q = math.floor(fade * 50 + 0.5) / 50
		if q ~= lastFade then
			lastFade = q
			local seq: NumberSequence
			if typeof(alongCurve) == "number" then
				seq = NumberSequence.new(math.clamp(alongCurve + (1 - alongCurve) * q, 0, 1))
			else
				local keys = {}
				for i = 0, 7 do
					local s = i / 7
					local v = Curves.sample(alongCurve, s)
					table.insert(keys, NumberSequenceKeypoint.new(s, math.clamp(v + (1 - v) * q, 0, 1)))
				end
				seq = NumberSequence.new(keys)
			end
			for _, beam in beams do
				beam.Transparency = seq
			end
		end
		return going
	end
	return update, function()
		for _, p in points do
			giveAttachment(p)
		end
	end
end

-- A crisp circle drawn by four curved beams (a quarter each): telegraph rims, expanding rings of light.
-- Beam control points sit at Attachment0 + its X axis * CurveSize0 and Attachment1 - its X axis * CurveSize1,
-- so each attachment's X axis points along the circle; 0.5523 * r makes a quarter-circle Bezier.
local QUARTER = 4 / 3 * math.tan(math.pi / 8)
local function circleBeams(track: any, ctx: Ctx): ({ Attachment }, { Beam })
	local points: { Attachment } = {}
	for _ = 1, 4 do
		table.insert(points, takeAttachment())
	end
	local beams: { Beam } = {}
	for i = 1, 4 do
		local b = beamFrom(track, ctx)
		b.Segments = 12
		b.Attachment0 = points[i]
		b.Attachment1 = points[i % 4 + 1]
		b.Parent = points[i]
		table.insert(beams, b)
	end
	return points, beams
end

local function placeCircle(points: { Attachment }, beams: { Beam }, center: CFrame, radius: number, width: number)
	for i, a in points do
		local angle = (i - 1) * math.pi / 2
		local radial = center * CFrame.Angles(0, -angle, 0)
		-- The points run +X, +Z, -X, -Z of the centre; at each the X axis turns to the next one's side.
		a.WorldCFrame = radial * CFrame.new(radius, 0, 0) * CFrame.Angles(0, math.rad(-90), 0)
	end
	for _, b in beams do
		b.CurveSize0 = radius * QUARTER
		b.CurveSize1 = radius * QUARTER
		b.Width0 = width
		b.Width1 = width
	end
end

RUNNERS.circle = function(track: any, ctx: Ctx)
	local points, beams = circleBeams(track, ctx)
	local offset = localCFrame(track, ctx.scale)
	local fadeCurve = track.transparency or { 0, 1 }
	local function update(t: number, _: number): boolean
		local k, going = progress(track, ctx, t)
		local radius = math.max(Curves.sample(track.radius or { 1, 8 }, k) * ctx.scale, 0.05)
		local width = math.max(Curves.sample(track.width or 0.4, k) * ctx.scale, 0.01)
		placeCircle(points, beams, ctx.base() * offset, radius, width)
		local seq = NumberSequence.new(math.clamp(Curves.sample(fadeCurve, k), 0, 1))
		for _, b in beams do
			b.Transparency = seq
		end
		return going
	end
	return update, function()
		for _, p in points do
			giveAttachment(p)
		end
	end
end

-- A path in the effect's own space (studs, scaled), from track data.
local function pathOf(spec: any, scale: number): Curves.Path
	local kind = if typeof(spec) == "table" then spec.kind else nil
	if kind == "spiral" then
		return Curves.spiral(CFrame.identity, num(spec.r0, 1) * scale, num(spec.r1, 3) * scale, num(spec.turns, 2), num(spec.height, 6) * scale)
	elseif kind == "orbit" then
		return Curves.spiral(CFrame.identity, num(spec.radius, 3) * scale, num(spec.radius, 3) * scale, num(spec.turns, 1), num(spec.height, 0) * scale)
	elseif kind == "points" and typeof(spec.points) == "table" then
		local pts = {}
		for _, p in spec.points do
			table.insert(pts, vec(p, Vector3.zero) * scale)
		end
		return if spec.smooth == false then Curves.polyline(pts) else Curves.catmullRom(pts)
	elseif kind == "line" then
		return Curves.polyline({ vec(spec.from, Vector3.zero) * scale, vec(spec.to, Vector3.new(0, 0, -10)) * scale })
	end
	local s = if typeof(spec) == "table" then spec else {}
	return Curves.arc(CFrame.identity, num(s.radius, 4) * scale, num(s.from, 60), num(s.to, -60))
end

-- A ribbon swept along a path by a moving trail: spin attacks, spirals rising round a hero, orbits, a
-- wind gust's swirl. (Single fast slashes look smoother as a slash track: one textured particle.)
RUNNERS.ribbon = function(track: any, ctx: Ctx)
	local brush = takePart("block")
	brush.Size = Vector3.new(0.2, 0.2, 0.2)
	local path = pathOf(track.path, ctx.scale)
	local offset = localCFrame(track, ctx.scale)
	local width = num(track.width, 1.5) * ctx.scale
	local upright = track.across == "upright"
	local a0 = Instance.new("Attachment")
	local a1 = Instance.new("Attachment")
	a0.Position = if upright then Vector3.new(0, -width / 2, 0) else Vector3.new(-width / 2, 0, 0)
	a1.Position = if upright then Vector3.new(0, width / 2, 0) else Vector3.new(width / 2, 0, 0)
	a0.Parent = brush
	a1.Parent = brush
	local spec = if typeof(track.trail) == "table" then track.trail else {}
	local trail = Instance.new("Trail")
	trail.Attachment0, trail.Attachment1 = a0, a1
	trail.Color = if ctx.tint then ColorSequence.new(tinted(ctx, Curves.sampleColor(spec.color or "#ffffff", 0))) else Curves.colorSequence(spec.color or "#ffffff")
	trail.Transparency = Curves.numberSequence(spec.transparency or { 0, 1 })
	trail.WidthScale = Curves.numberSequence(spec.width or { 1, 0 })
	local lifetime = num(spec.lifetime, 0.25)
	trail.Lifetime = lifetime
	trail.MinLength = 0.05
	trail.FaceCamera = false
	trail.LightEmission = num(spec.lightEmission, 1)
	trail.LightInfluence = num(spec.lightInfluence, 0)
	pcall(function()
		trail.Brightness = num(spec.brightness, 1)
	end)
	if typeof(spec.texture) == "string" and spec.texture ~= "" then
		trail.Texture = spec.texture
		trail.TextureMode = enumItem(Enum.TextureMode, spec.textureMode, Enum.TextureMode.Stretch)
	end
	trail.Enabled = false
	trail.Parent = brush
	local duration = math.max(num(track.duration, 0.3), 1e-3)
	local ease = Curves.easer(track.ease or "quadOut")
	local started = false
	local function update(t: number, _: number): boolean
		local k = if ctx.persistent and track.loop then (t % duration) / duration else math.clamp(t / duration, 0, 1)
		brush.CFrame = ctx.base() * offset * path:frame(ease(k))
		if not started then
			started = true
			trail.Enabled = true -- after the first placement: no streak from where the pooled part was
		end
		if ctx.persistent and track.loop then
			return true
		end
		if t >= duration then
			trail.Enabled = false
		end
		return t < duration + lifetime
	end
	return update, function()
		givePart(brush)
	end
end

local function soundAt(track: any, ctx: Ctx)
	local name = track.sound
	if typeof(name) ~= "string" then
		return
	end
	local at = ctx.base() * localCFrame(track, ctx.scale)
	if string.match(name, "^rbxasset") then
		local a = takeAttachment(at)
		local s = Instance.new("Sound")
		s.SoundId = name
		s.Volume = num(track.volume, 0.6)
		local pitch = vec(track.pitch, Vector3.new(0.95, 1.05, 0))
		s.PlaybackSpeed = rng:NextNumber(math.min(pitch.X, pitch.Y), math.max(pitch.X, pitch.Y))
		s.RollOffMaxDistance = num(track.distance, 150)
		s.Parent = a
		s:Play()
		task.delay(math.max(s.TimeLength, 1) + 4, function()
			giveAttachment(a)
		end)
		return
	end
	local Audio = sibling("ShurikenAudio")
	if Audio and Audio.play then
		local pitch = vec(track.pitch, Vector3.new(1, 1, 0))
		pcall(Audio.play, name, at, { volume = track.volume, pitch = rng:NextNumber(math.min(pitch.X, pitch.Y), math.max(pitch.X, pitch.Y)) })
	end
end

RUNNERS.sound = function(track: any, ctx: Ctx)
	soundAt(track, ctx)
	return nil, nil
end

RUNNERS.shake = function(track: any, ctx: Ctx)
	if not RunService:IsClient() then
		return nil, nil
	end
	local cam = camera()
	local falloff = 1
	local radius = num(track.radius, 0)
	if cam and radius > 0 then
		falloff = math.clamp(1 - (cam.CFrame.Position - ctx.base().Position).Magnitude / radius, 0, 1)
	end
	if falloff > 0 then
		shakeCamera(num(track.magnitude, 1.5) * falloff, num(track.duration, 0.25))
	end
	return nil, nil
end

local hitStop: (target: Instance, seconds: number?) -> ()

RUNNERS.hitstop = function(track: any, ctx: Ctx)
	if ctx.target then
		hitStop(ctx.target, num(track.seconds, 0.06))
	end
	return nil, nil
end

RUNNERS.highlight = function(track: any, ctx: Ctx)
	local model = ctx.target
	if not model or highlightsLive >= 28 then
		return nil, nil -- Roblox draws at most 31 Highlights at once
	end
	highlightsLive += 1
	local h = Instance.new("Highlight")
	h.Name = "ShurikenFlash"
	h.FillColor = tinted(ctx, hex(track.color, Color3.new(1, 1, 1)))
	h.OutlineColor = hex(track.outline or track.color, Color3.new(1, 1, 1))
	h.DepthMode = Enum.HighlightDepthMode.Occluded
	h.FillTransparency = 1
	h.OutlineTransparency = 1
	h.Adornee = model
	h.Parent = model
	local fill = track.transparency or { 0.15, 1 }
	local outline = track.outlineTransparency or { 0.3, 1 }
	local function update(t: number, _: number): boolean
		local k, going = progress(track, ctx, t)
		h.FillTransparency = math.clamp(Curves.sample(fill, k), 0, 1)
		h.OutlineTransparency = math.clamp(Curves.sample(outline, k), 0, 1)
		return going and h.Parent ~= nil
	end
	return update, function()
		highlightsLive -= 1
		h:Destroy()
	end
end

RUNNERS.screen = function(track: any, ctx: Ctx)
	local cam = camera()
	if not RunService:IsClient() or not cam then
		return nil, nil
	end
	local within = num(track.within, 0)
	local at = ctx.base().Position
	if within > 0 and (cam.CFrame.Position - at).Magnitude > within then
		return nil, nil
	end
	local Screen = sibling("ShurikenScreenFX")
	if Screen and Screen.cue then
		pcall(Screen.cue, track.fx, track, at)
	else
		warnOnce("screenfx", "screen tracks need the ShurikenScreenFX module (vfx_runtime puts it in the game)")
	end
	return nil, nil
end

-- Chunks thrown out under gravity that bounce once on the ground, settle and fade: rocks, ice, metal.
RUNNERS.debris = function(track: any, ctx: Ctx)
	local budget = Effects.budget()
	local count = math.max(1, math.round(num(track.count, 6) * (ctx.opts.count or 1) * budget.particles))
	local origin = ctx.base() * localCFrame(track, ctx.scale)
	local hit = groundBelow(origin.Position, 60)
	local floor = if hit then hit.Position.Y else -math.huge
	local sizes = vec(track.size, Vector3.new(0.4, 1, 0))
	local speeds = vec(track.speed, Vector3.new(20, 40, 0))
	local spread = math.rad(num(track.spread, 50))
	local gravity = num(track.gravity, 120)
	local bounce = num(track.bounce, 0.35)
	local life = vec(track.lifetime, Vector3.new(1.2, 2, 0))
	local colors = if typeof(track.color) == "table" then track.color else { track.color or "#8a7f73" }
	local shape = if track.shape == "wedge" then "wedge" elseif track.shape == "ball" then "sphere" else "block"
	type Piece = { part: BasePart, position: Vector3, velocity: Vector3, spin: Vector3, angle: Vector3, size: Vector3, dies: number }
	local pieces: { Piece } = {}
	local longest = 0
	for _ = 1, count do
		local p = takePart(shape)
		p.Material = enumItem(Enum.Material, track.material, Enum.Material.Slate)
		p.Color = tinted(ctx, hex(colors[rng:NextInteger(1, #colors)], Color3.new(0.5, 0.5, 0.5)))
		p.Transparency = 0
		local s = rng:NextNumber(sizes.X, sizes.Y) * ctx.scale
		local size = Vector3.new(s, s * rng:NextNumber(0.6, 1), s * rng:NextNumber(0.7, 1.2))
		p.Size = size
		local yaw = rng:NextNumber(0, 2 * math.pi)
		local tilt = rng:NextNumber(0, spread)
		local dir = (origin.Rotation * CFrame.Angles(0, yaw, 0) * CFrame.Angles(tilt, 0, 0)).UpVector
		local dies = rng:NextNumber(life.X, life.Y)
		longest = math.max(longest, dies)
		table.insert(pieces, {
			part = p,
			position = origin.Position,
			velocity = dir * rng:NextNumber(speeds.X, speeds.Y) * ctx.scale,
			spin = Vector3.new(rng:NextNumber(-12, 12), rng:NextNumber(-12, 12), rng:NextNumber(-12, 12)),
			angle = Vector3.zero,
			size = size,
			dies = dies,
		})
	end
	local function update(t: number, dt: number): boolean
		for _, piece in pieces do
			local v = piece.velocity - Vector3.new(0, gravity * dt, 0)
			local pos = piece.position + v * dt
			local rest = floor + piece.size.Y / 2
			if pos.Y < rest then
				pos = Vector3.new(pos.X, rest, pos.Z)
				v = Vector3.new(v.X * 0.55, math.abs(v.Y) * bounce, v.Z * 0.55)
				piece.spin *= 0.5
			end
			piece.position, piece.velocity = pos, v
			piece.angle += piece.spin * dt
			local fadeFrom = piece.dies * 0.7
			piece.part.Transparency = if t > fadeFrom then math.clamp((t - fadeFrom) / (piece.dies - fadeFrom), 0, 1) else 0
			piece.part.CFrame = CFrame.new(pos) * CFrame.Angles(piece.angle.X, piece.angle.Y, piece.angle.Z)
		end
		return t < longest
	end
	return update, function()
		for _, piece in pieces do
			givePart(piece.part)
		end
	end
end

-- A decal laid on the ground (scorch marks, magic circles, cracks): fades, tints and spins over the track.
RUNNERS.decal = function(track: any, ctx: Ctx)
	if typeof(track.texture) ~= "string" then
		return nil, nil
	end
	local at = ctx.base() * localCFrame(track, ctx.scale)
	local place = at
	if track.ground ~= false then
		local hit = groundBelow(at.Position, 30)
		if hit then
			local n = hit.Normal
			local look = at.LookVector - n * at.LookVector:Dot(n)
			if look.Magnitude < 1e-3 then
				look = n:Cross(Vector3.xAxis)
			end
			place = CFrame.lookAt(hit.Position + n * 0.04, hit.Position + n * 0.04 + look.Unit, n)
		end
	end
	local size = vec(track.size, Vector3.new(8, 8, 0)) * ctx.scale
	local h = if size.Y > 0 then size.Y else size.X
	local p = takePart("block")
	p.Size = Vector3.new(size.X, 0.05, h)
	local d = Instance.new("Decal")
	d.Face = Enum.NormalId.Top
	d.Texture = track.texture
	d.Parent = p
	local spin = num(track.spin, 0)
	local fade = track.transparency or { keys = { { 0, 1 }, { 0.1, 0 }, { 0.75, 0 }, { 1, 1 } } }
	local color = track.color or "#ffffff"
	local function update(t: number, _: number): boolean
		local k, going = progress(track, ctx, t)
		d.Transparency = math.clamp(Curves.sample(fade, k), 0, 1)
		d.Color3 = tinted(ctx, Curves.sampleColor(color, k))
		p.CFrame = place * CFrame.Angles(0, math.rad(spin * t), 0)
		return going
	end
	return update, function()
		givePart(p)
	end
end

------------------------------------------------------------------------------------------- Playing effects
local function noopHandle(a: Attachment?): Handle
	local att = a or Instance.new("Attachment")
	return {
		attachment = att,
		stop = function() end,
		destroy = function() end,
		alive = function()
			return false
		end,
		move = function(_: CFrame) end,
	}
end

local function playLocal(name: string, where: any, opts: Options?, persistent: boolean?): Handle
	local tpl = template(name)
	local at = cframeOf(where)
	if not tpl or not at then
		return noopHandle()
	end
	local kind = tpl:GetAttribute("Kind")
	if kind == "trail" or kind == "beam" then
		warnOnce("kind:" .. name, name .. " is a " .. tostring(kind) .. ": use Effects." .. tostring(kind) .. "()")
		return noopHandle()
	end
	local o: Options = opts or {}
	local isPersistent = if persistent ~= nil then persistent else kind == "persistent"
	local radius = num(tpl:GetAttribute("Radius"), 8) * (o.scale or 1)
	if not isPersistent and not worthPlaying(at.Position, radius, o.force) then
		return noopHandle()
	end
	local follow = if o.follow ~= nil then o.follow else isPersistent
	local anchor = if follow then anchorOf(where) else nil
	local parent = if anchor and anchor:IsA("Attachment") then anchor.Parent else anchor
	local host = takeHost(tpl, at, parent)
	if anchor and anchor:IsA("Attachment") then
		placeHost(host, anchor.WorldCFrame)
	end
	local hostAttachment = host.attachment
	local particlesFor = emitAll(host, o, isPersistent)
	local longestLife = 0
	for _, pair in host.emitters do
		longestLife = math.max(longestLife, pair.tpl.Lifetime.Max)
	end
	effectsLive += 1
	local ctx: Ctx = {
		base = function(): CFrame
			return if hostAttachment.Parent then hostAttachment.WorldCFrame else at
		end,
		opts = o,
		scale = o.scale or 1,
		tint = o.color,
		target = o.target,
		persistent = isPersistent,
	}
	-- Lights in the template (v3 effects): a flash that fades over FlashDuration, or a steady glow.
	for _, c in tpl:GetChildren() do
		if c:IsA("PointLight") then
			local flash = num(c:GetAttribute("FlashDuration"), 0.2)
			local light = c:Clone()
			if o.color then
				light.Color = o.color
			end
			light.Parent = hostAttachment
			if flash > 0 and not isPersistent then
				TweenService:Create(light, TweenInfo.new(flash, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Brightness = 0 }):Play()
				task.delay(flash + 0.05, function()
					light:Destroy()
				end)
			end
		end
	end
	local tracks = timelineOf(tpl)
	local budget = Effects.budget()
	local nextTrack = 1
	type Active = { update: (t: number, dt: number) -> boolean, cleanup: (() -> ())?, start: number }
	local active: { Active } = {}
	local cleanups: { () -> () } = {}
	local stopped = false
	local finished = false
	local started = os.clock()
	local duration = math.max(num(tpl:GetAttribute("Duration"), 2), particlesFor)

	local function finish()
		if finished then
			return
		end
		finished = true
		effectsLive -= 1
		for _, a in active do
			if a.cleanup then
				a.cleanup()
			end
		end
		table.clear(active)
		for _, c in cleanups do
			c()
		end
		for _, c in hostAttachment:GetChildren() do
			if c:IsA("Light") then
				c:Destroy()
			end
		end
		local left = if isPersistent then longestLife else math.max(0, particlesFor - (os.clock() - started))
		if anchor then
			task.delay(left + 0.1, function()
				hostAttachment:Destroy()
				for _, x in host.extras do
					x.attachment:Destroy()
				end
			end)
		else
			releaseHost(host, left + 0.1)
		end
	end

	local function startTrack(track: any, now: number)
		if typeof(track.detail) == "string" and (RANK[track.detail] or 1) > budget.rank then
			return
		end
		local runner = RUNNERS[track.type]
		if track.type == "spawn" then
			if typeof(track.effect) == "string" and track.effect ~= name then
				playLocal(track.effect, ctx.base() * localCFrame(track, ctx.scale), o, false)
			end
			return
		elseif not runner then
			warnOnce("track:" .. tostring(track.type), ("%s: unknown track type %s"):format(name, tostring(track.type)))
			return
		end
		local ok, update, cleanup = pcall(runner, track, ctx)
		if not ok then
			warnOnce("runner:" .. name .. tostring(track.type), ("%s: %s track failed: %s"):format(name, tostring(track.type), tostring(update)))
			return
		end
		if update then
			table.insert(active, { update = update, cleanup = cleanup, start = now })
		elseif cleanup then
			table.insert(cleanups, cleanup)
		end
	end

	local needsFrames = #tracks > 0
	if not needsFrames and not isPersistent then
		task.delay(duration, finish)
	end
	local job: Job = function(dt: number, now: number): boolean
		if finished then
			return false
		end
		local t = now - started
		while not stopped and nextTrack <= #tracks and num(tracks[nextTrack].at, 0) <= t do
			startTrack(tracks[nextTrack], now)
			nextTrack += 1
		end
		for i = #active, 1, -1 do
			local a = active[i]
			local ok, going = pcall(a.update, now - a.start, dt)
			if not ok or not going then
				if not ok then
					warnOnce("update:" .. name, ("%s: %s"):format(name, tostring(going)))
				end
				if a.cleanup then
					a.cleanup()
				end
				table.remove(active, i)
			end
		end
		if stopped or not isPersistent then
			local pending = not stopped and nextTrack <= #tracks
			if #active == 0 and not pending and (stopped or t >= duration) then
				finish()
				return false
			end
		end
		return true
	end
	if needsFrames then
		run(job)
	end

	local function stop()
		if stopped then
			return
		end
		stopped = true
		for _, pair in host.emitters do
			pair.live.Enabled = false
		end
		-- Tracks end now (a persistent effect's loops; a burst stopped early).
		for i = #active, 1, -1 do
			local a = active[i]
			if a.cleanup then
				a.cleanup()
			end
			table.remove(active, i)
		end
		if not needsFrames then
			finish()
		end
	end
	return {
		attachment = hostAttachment,
		stop = stop,
		destroy = function()
			stop()
			finish()
		end,
		alive = function()
			return not finished
		end,
		move = function(to: CFrame)
			placeHost(host, to)
		end,
	}
end

--- Plays an effect by name at a Vector3, CFrame, part, attachment or model. On the server it is relayed
--- to the clients (see opts.players / except / radius) and returns nil. Persistent effects keep going
--- until handle.stop().
function Effects.play(name: string, where: any, opts: Options?): Handle?
	if relaying() then
		local tpl = template(name)
		if tpl and tpl:GetAttribute("Kind") == "persistent" and not (opts and opts.seconds) then
			warnOnce("persistent-server:" .. name, name .. " stays on: from the server it runs opts.seconds (default 5) on each client; attach it on the clients to stop it yourself")
		end
		relay(name, where, nil, opts)
		return nil
	end
	return playLocal(name, where, opts, nil)
end

--- A one-shot effect (same as play; kept for older code).
function Effects.burst(name: string, where: any, opts: Options?): Handle?
	return Effects.play(name, where, opts)
end

--- A persistent effect (aura, fire, smoke) on a part/attachment/position that follows it. handle.stop()
--- ends it (particles die out), handle.destroy() removes it at once. Client-side: call it on each client.
function Effects.attach(name: string, where: any, opts: Options?): Handle?
	local o: Options = if opts then table.clone(opts) else {}
	if o.follow == nil then
		o.follow = true
	end
	if relaying() then
		warnOnce("attach-server", "Effects.attach on the server plays on each client for opts.seconds (default 5) and misses players who join later: attach on the clients for effects that stay")
		relay(name, where, nil, o)
		return nil
	end
	return playLocal(name, where, o, true)
end

--- A trail on a part (a blade, a limb): between two attachments, or along the part's longest side.
function Effects.trail(name: string, part: BasePart, from: Attachment?, to: Attachment?): Trail?
	local tpl = template(name)
	if not (tpl and tpl:IsA("Trail")) then
		return nil
	end
	local a0: Attachment
	local a1: Attachment
	if from and to then
		a0, a1 = from, to
	else
		local s = part.Size
		local axis = if s.X >= s.Y and s.X >= s.Z then Vector3.xAxis elseif s.Y >= s.Z then Vector3.yAxis else Vector3.zAxis
		local half = axis * (s:Dot(axis) / 2)
		a0 = Instance.new("Attachment")
		a0.Name = name .. "0"
		a0.Position = half
		a0.Parent = part
		a1 = Instance.new("Attachment")
		a1.Name = name .. "1"
		a1.Position = -half
		a1.Parent = part
	end
	local t = tpl:Clone()
	t.Attachment0 = a0
	t.Attachment1 = a1
	t.Parent = part
	return t
end

local function attachmentOf(x: Instance): Attachment?
	if x:IsA("Attachment") then
		return x
	end
	if x:IsA("BasePart") then
		local a = Instance.new("Attachment")
		a.Parent = x
		return a
	end
	return nil
end

--- A beam between two attachments (or parts).
function Effects.beam(name: string, from: Instance, to: Instance): Beam?
	local tpl = template(name)
	if not (tpl and tpl:IsA("Beam")) then
		return nil
	end
	local a0 = attachmentOf(from)
	local a1 = attachmentOf(to)
	if not a0 or not a1 then
		return nil
	end
	local b = tpl:Clone()
	b.Attachment0 = a0
	b.Attachment1 = a1
	b.Parent = a0.Parent
	return b
end

------------------------------------------------------------------------------------------- Projectiles
export type ProjectileOptions = {
	from: Vector3 | CFrame | Instance,
	to: (Vector3 | Instance)?, -- a point, or a part/model to hit (its position when fired)
	direction: Vector3?, -- instead of to: fly this way for \`range\` studs
	range: number?, -- default 120
	speed: number?, -- studs per second (default 80)
	path: string?, -- "straight" (default), "arc", "homing", "spiral", "wave"
	height: number?, -- arc: apex above the higher end (default: a fifth of the distance)
	turnRate: number?, -- homing: degrees per second (default 240)
	target: Instance?, -- homing: what it chases (default: \`to\` when it's a part or model)
	radius: number?, -- spiral and wave: how far it strays from the line (default 1.5)
	turns: number?, -- spiral and wave: turns per 10 studs (default 1)
	body: string?, -- a persistent effect that rides the projectile (the fireball itself)
	impact: string?, -- a one-shot effect where it ends, facing out of what it hit
	collide: boolean?, -- stop at the first part in the way (raycast each frame; default true)
	ignore: { Instance }?, -- what it flies through (the caster's character)
	color: Color3?,
	scale: number?,
	onHit: ((position: Vector3, part: BasePart?) -> ())?, -- client only: the server decides damage
}

local function positionOfInstance(x: Instance): Vector3?
	local cf = cframeOf(x)
	return if cf then cf.Position else nil
end

local function projectileEnds(o: ProjectileOptions): (Vector3, Vector3)
	local fromCf = cframeOf(o.from) or CFrame.new()
	local start = fromCf.Position
	local finish: Vector3
	local to = o.to
	if typeof(to) == "Vector3" then
		finish = to
	elseif typeof(to) == "Instance" then
		finish = positionOfInstance(to) or start + fromCf.LookVector * (o.range or 120)
	else
		local dir = if o.direction and o.direction.Magnitude > 0 then o.direction.Unit else fromCf.LookVector
		finish = start + dir * (o.range or 120)
	end
	return start, finish
end

local function projectilePath(o: ProjectileOptions, start: Vector3, finish: Vector3): Curves.Path
	local kind = o.path or "straight"
	local distance = (finish - start).Magnitude
	if kind == "arc" then
		return Curves.ballistic(start, finish, o.height or distance / 5)
	elseif kind == "spiral" or kind == "wave" then
		local radius = o.radius or 1.5
		local turns = (o.turns or 1) * distance / 10
		local frame = CFrame.lookAt(start, finish + Vector3.new(0, 1e-4, 0))
		return Curves.fromFunction(function(s: number): Vector3
			local angle = s * turns * 2 * math.pi
			local envelope = math.min(1, s * 6, (1 - s) * 6) -- leaves the hand and reaches the target on the line
			local side = if kind == "spiral" then Vector3.new(math.cos(angle), math.sin(angle), 0) else Vector3.new(math.sin(angle), 0, 0)
			return (frame * CFrame.new(side * radius * envelope + Vector3.new(0, 0, -distance * s))).Position
		end, math.clamp(math.ceil(turns * 24), 32, 2000))
	end
	return Curves.polyline({ start, finish })
end

--- How long a projectile flies (seconds): the server uses it to time the hit of what clients see.
function Effects.flightTime(opts: ProjectileOptions): number
	local start, finish = projectileEnds(opts)
	local speed = math.max(opts.speed or 80, 1)
	if opts.path == "homing" then
		return (finish - start).Magnitude / speed * 1.15
	end
	return projectilePath(opts, start, finish).length / speed
end

--- A visual projectile flying from \`from\` to \`to\` (or along \`direction\`): straight, a lobbed arc, homing,
--- spiralling or weaving; \`body\` rides it, \`impact\` plays where it ends. On the server it is relayed; time
--- the hit there with Effects.flightTime(opts) (clients only show it).
function Effects.projectile(opts: ProjectileOptions): Handle?
	if relaying() then
		local o = table.clone(opts)
		o.onHit = nil
		relay("__projectile", o, nil, nil)
		return nil
	end
	local start, finish = projectileEnds(opts)
	if not worthPlaying(start:Lerp(finish, 0.5), (finish - start).Magnitude / 2, false) then
		return nil
	end
	local speed = math.max(opts.speed or 80, 1)
	local kind = opts.path or "straight"
	local path = if kind == "homing" then nil else projectilePath(opts, start, finish)
	local head = takeAttachment(CFrame.lookAt(start, finish + Vector3.new(0, 1e-4, 0)))
	local fx: Options = { color = opts.color, scale = opts.scale, follow = true, force = true }
	local body = if opts.body then playLocal(opts.body, head, fx, true) else nil
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ignore: { Instance } = { fxFolder() }
	local extra: { Instance } = opts.ignore or {}
	for _, x in extra do
		table.insert(ignore, x)
	end
	params.FilterDescendantsInstances = ignore
	local collide = opts.collide ~= false
	local target = opts.target or (if typeof(opts.to) == "Instance" then opts.to else nil)
	local position = start
	local velocity = (finish - start).Unit * speed
	local travelled = 0
	local limit = if path then path.length else (finish - start).Magnitude * 2.5
	local done = false
	local function land(at: Vector3, normal: Vector3?, part: BasePart?)
		if done then
			return
		end
		done = true
		if opts.impact then
			local face = if normal then CFrame.lookAt(at, at + normal) * CFrame.Angles(-math.pi / 2, 0, 0) else CFrame.new(at)
			playLocal(opts.impact, face, { color = opts.color, scale = opts.scale, force = true }, false)
		end
		if body then
			body.stop()
		end
		task.delay(0.6, function()
			giveAttachment(head)
		end)
		if opts.onHit then
			task.spawn(opts.onHit, at, part)
		end
	end
	run(function(dt: number, _: number): boolean
		if done then
			return false
		end
		local nextPosition: Vector3
		if path then
			travelled = math.min(travelled + speed * dt, path.length)
			nextPosition = path:at(if path.length > 0 then travelled / path.length else 1)
		else
			local aim = if target then positionOfInstance(target) else finish
			velocity = Curves.steer(position, velocity, aim or finish, opts.turnRate or 240, dt)
			nextPosition = position + velocity * dt
			travelled += speed * dt
			if aim and (aim - nextPosition).Magnitude <= speed * dt then
				nextPosition = aim
				travelled = limit
			end
		end
		local move = nextPosition - position
		if collide and move.Magnitude > 1e-4 then
			local hit = workspace:Raycast(position, move, params)
			if hit then
				head.WorldPosition = hit.Position
				land(hit.Position, hit.Normal, hit.Instance :: BasePart)
				return false
			end
		end
		if move.Magnitude > 1e-4 then
			head.WorldCFrame = CFrame.lookAt(nextPosition, nextPosition + move)
			if body then
				body.move(head.WorldCFrame)
			end
		end
		position = nextPosition
		if travelled >= limit then
			land(position, nil, nil)
			return false
		end
		return true
	end)
	return {
		attachment = head,
		stop = function()
			land(position, nil, nil)
		end,
		destroy = function()
			done = true
			if body then
				body.destroy()
			end
			giveAttachment(head)
		end,
		alive = function()
			return not done
		end,
		move = function(_: CFrame) end,
	}
end

------------------------------------------------------------------------------------------- Lightning
export type LightningOptions = {
	color: Color3?, -- the glow (the core is white)
	width: number?, -- core width in studs (default 0.25; the glow is 4x)
	seconds: number?, -- how long it crackles (default 0.25)
	rate: number?, -- new shapes per second (default 18)
	segments: number?,
	amplitude: number?, -- kinks as a fraction of the length (default 0.12)
	branches: number?, -- side forks (default 2)
	impact: string?, -- an effect at the far end
}

local function boltBetween(a: Vector3, b: Vector3, o: LightningOptions, seconds: number)
	local glow = o.color or Color3.fromRGB(150, 200, 255)
	local width = o.width or 0.25
	local white = Color3.new(1, 1, 1)
	local function bolt(from: Vector3, to: Vector3, w: number)
		local track = {
			duration = seconds,
			segments = 1,
			jag = { segments = o.segments or math.clamp(math.floor((to - from).Magnitude / 3), 4, 16), amplitude = o.amplitude or 0.12, rate = o.rate or 18 },
			fade = { keys = { { 0, 0 }, { 0.7, 0.2 }, { 1, 1 } } },
			lightEmission = 1,
			brightness = 3,
		}
		local base = CFrame.lookAt(from, to + Vector3.new(0, 1e-4, 0))
		local length = (to - from).Magnitude
		local function layer(color: Color3, lw: number, transparency: number)
			local t = table.clone(track)
			t.color = color:ToHex()
			t.width = { lw, lw }
			t.transparency = transparency
			t.from = { 0, 0, 0 }
			t.to = { 0, 0, -length }
			local ctx: Ctx = {
				base = function(): CFrame
					return base
				end,
				opts = { force = true },
				scale = 1,
				tint = nil,
				target = nil,
				persistent = false,
			}
			local update, cleanup = RUNNERS.beam(t, ctx)
			if update then
				local started = os.clock()
				run(function(dt: number, now: number): boolean
					local going = update(now - started, dt)
					if not going and cleanup then
						cleanup()
					end
					return going
				end)
			end
		end
		layer(glow, w * 4, 0.55)
		layer(white, w, 0)
	end
	bolt(a, b, width)
	local rngLocal = Random.new()
	for _ = 1, o.branches or 2 do
		local s = rngLocal:NextNumber(0.25, 0.7)
		local p = a:Lerp(b, s)
		local away = (b - a).Magnitude * rngLocal:NextNumber(0.15, 0.3)
		local dir = ((b - a).Unit + Vector3.new(rngLocal:NextNumber(-1, 1), rngLocal:NextNumber(-1, 1), rngLocal:NextNumber(-1, 1))).Unit
		bolt(p, p + dir * away, width * 0.6)
	end
	if o.impact then
		playLocal(o.impact, b, { color = o.color, force = true }, false)
	end
end

--- A crackling bolt between two points (or parts): a white core in a coloured glow, re-shaped many times
--- a second, with side forks. On the server it is relayed.
function Effects.lightning(from: Vector3 | Instance, to: Vector3 | Instance, opts: LightningOptions?)
	if relaying() then
		relay("__lightning", from, to, opts)
		return
	end
	local a = if typeof(from) == "Vector3" then from else positionOfInstance(from)
	local b = if typeof(to) == "Vector3" then to else positionOfInstance(to)
	if not a or not b or not worthPlaying(a:Lerp(b, 0.5), (b - a).Magnitude / 2, false) then
		return
	end
	local o: LightningOptions = opts or {}
	boltBetween(a, b, o, o.seconds or 0.25)
end

--- Chain lightning: a bolt from each point to the next, one after another (\`gap\` seconds apart).
function Effects.chain(points: { Vector3 | Instance }, opts: LightningOptions?, gap: number?)
	if relaying() then
		relay("__chain", points, gap, opts)
		return
	end
	for i = 1, #points - 1 do
		task.delay((i - 1) * (gap or 0.08), function()
			Effects.lightning(points[i], points[i + 1], opts)
		end)
	end
end

------------------------------------------------------------------------------------------- Telegraphs
export type TelegraphOptions = {
	shape: string?, -- "circle" (default) or "rect" (a line attack: width x length, ahead of the CFrame)
	radius: number?, -- circle (default 8)
	width: number?, -- rect (default 6)
	length: number?, -- rect (default 20)
	seconds: number?, -- time until it hits: the fill grows over it (default 1)
	color: Color3?, -- default danger red
	effect: string?, -- played at the centre when it fills
	onDone: (() -> ())?,
}

--- A warning shape on the ground that fills up over \`seconds\`, then (optionally) plays an effect: a bright
--- rim, a faint area and a growing fill, pulsing so it reads in a busy fight. On the server it is relayed.
function Effects.telegraph(where: Vector3 | CFrame, opts: TelegraphOptions?): Handle?
	if relaying() then
		local o: TelegraphOptions = if opts then table.clone(opts) else {}
		o.onDone = nil
		relay("__telegraph", where, nil, o)
		return nil
	end
	local o: TelegraphOptions = opts or {}
	local cf = cframeOf(where) or CFrame.new()
	local hit = groundBelow(cf.Position, 40)
	local look = cf.LookVector * Vector3.new(1, 0, 1)
	if look.Magnitude < 1e-3 then
		look = Vector3.new(0, 0, -1)
	end
	local ground = if hit then hit.Position.Y + 0.06 else cf.Position.Y
	local center = CFrame.lookAt(Vector3.new(cf.X, ground, cf.Z), Vector3.new(cf.X, ground, cf.Z) + look.Unit)
	local color = o.color or Color3.fromRGB(255, 59, 48)
	local seconds = math.max(o.seconds or 1, 0.05)
	local rect = o.shape == "rect"
	local radius = o.radius or 8
	local width, length = o.width or 6, o.length or 20
	local area = takePart(if rect then "block" else "cylinder")
	local fill = takePart(if rect then "block" else "cylinder")
	for _, p in { area, fill } do
		p.Material = Enum.Material.Neon
		p.Color = color
	end
	local rimTrack = { color = color:ToHex(), lightEmission = 1, brightness = 2, faceCamera = true }
	local ctx: Ctx = {
		base = function(): CFrame
			return center
		end,
		opts = { force = true },
		scale = 1,
		tint = nil,
		target = nil,
		persistent = false,
	}
	local points: { Attachment } = {}
	local beams: { Beam } = {}
	if rect then
		for i = 1, 4 do
			local a = takeAttachment()
			table.insert(points, a)
			local b = beamFrom(rimTrack, ctx)
			b.Width0, b.Width1 = 0.35, 0.35
			table.insert(beams, b)
			b.Parent = a
			if i > 1 then
				b.Attachment0, b.Attachment1 = points[i - 1], a
			end
		end
		beams[1].Attachment0, beams[1].Attachment1 = points[4], points[1]
	else
		points, beams = circleBeams(rimTrack, ctx)
	end
	local corners = { Vector3.new(-width / 2, 0, 0), Vector3.new(width / 2, 0, 0), Vector3.new(width / 2, 0, -length), Vector3.new(-width / 2, 0, -length) }
	local function placeRim()
		if rect then
			for i, c in corners do
				points[i].WorldPosition = (center * CFrame.new(c)).Position
			end
		else
			placeCircle(points, beams, center, radius, 0.35)
		end
	end
	placeRim()
	local started = os.clock()
	local done = false
	local function cleanup()
		givePart(area)
		givePart(fill)
		for _, a in points do
			giveAttachment(a)
		end
	end
	run(function(_: number, now: number): boolean
		if done then
			return false
		end
		local t = now - started
		local k = math.clamp(t / seconds, 0, 1)
		local pulse = 0.5 + 0.5 * math.sin(t * 14)
		placeRim()
		if rect then
			area.Size = Vector3.new(width, 0.05, length)
			area.CFrame = center * CFrame.new(0, 0, -length / 2)
			fill.Size = Vector3.new(width, 0.06, math.max(length * k, 0.05))
			fill.CFrame = center * CFrame.new(0, 0.01, -length * k / 2)
		else
			area.Size = Vector3.new(0.05, radius * 2, radius * 2)
			area.CFrame = center * CFrame.Angles(0, 0, math.rad(90))
			fill.Size = Vector3.new(0.06, math.max(radius * 2 * k, 0.05), math.max(radius * 2 * k, 0.05))
			fill.CFrame = center * CFrame.new(0, 0.01, 0) * CFrame.Angles(0, 0, math.rad(90))
		end
		area.Transparency = 0.82 - 0.06 * pulse
		fill.Transparency = 0.62
		local rim = NumberSequence.new(0.1 * pulse)
		for _, b in beams do
			b.Transparency = rim
		end
		if t >= seconds then
			done = true
			if o.effect then
				playLocal(o.effect, center, { color = o.color, force = true }, false)
			end
			cleanup()
			if o.onDone then
				task.spawn(o.onDone)
			end
			return false
		end
		return true
	end)
	return {
		attachment = points[1],
		stop = function()
			if not done then
				done = true
				cleanup()
			end
		end,
		destroy = function()
			if not done then
				done = true
				cleanup()
			end
		end,
		alive = function()
			return not done
		end,
		move = function(to: CFrame)
			center = to
		end,
	}
end

------------------------------------------------------------------------------------------- Flashes, shake, hit-stop
export type FlashOptions = { color: Color3?, seconds: number?, outline: boolean? }

--- A hit flash on a model (Highlight): white by default, fading over 0.18 s. On the server it is relayed.
function Effects.flash(model: Instance, opts: FlashOptions?)
	if relaying() then
		relay("__flash", model, nil, opts)
		return
	end
	local o: FlashOptions = opts or {}
	local track = {
		color = (o.color or Color3.new(1, 1, 1)):ToHex(),
		duration = o.seconds or 0.18,
		transparency = { 0.05, 1 },
		outlineTransparency = if o.outline == false then 1 else { 0.2, 1 },
	}
	local ctx: Ctx = {
		base = function(): CFrame
			return CFrame.new()
		end,
		opts = {},
		scale = 1,
		tint = nil,
		target = model,
		persistent = false,
	}
	local update, cleanup = RUNNERS.highlight(track, ctx)
	if update then
		local started = os.clock()
		run(function(dt: number, now: number): boolean
			local going = update(now - started, dt)
			if not going and cleanup then
				cleanup()
			end
			return going
		end)
	end
end

--- Shake the camera: magnitude in degrees (1.5), seconds (0.25). On the server it shakes one player's
--- camera, or every player's when player is nil. Off under Reduce Motion and Effects.setShake(0).
function Effects.shake(magnitude: number?, seconds: number?, player: Player?)
	local m = magnitude or 1.5
	local d = seconds or 0.25
	if relaying() then
		local remote = remoteEvent()
		if remote and player then
			remote:FireClient(player, "__shake", m, d)
		elseif remote then
			remote:FireAllClients("__shake", m, d)
		end
		return
	end
	if RunService:IsClient() then
		shakeCamera(m, d)
	end
end

local frozen: { [AnimationTrack]: { speed: number, endsAt: number } } = {}

--- Freezes a character's (or model's) animations for a moment on impact: the hit lands. Uses
--- ShurikenAnimations.hitStop when the game has it.
function hitStop(target: Instance, seconds: number?)
	local duration = seconds or 0.06
	if relaying() then
		relay("__hitstop", target, duration, nil)
		return
	end
	local Anims = sibling("ShurikenAnimations")
	if Anims and Anims.hitStop then
		pcall(Anims.hitStop, target, duration)
		return
	end
	local animator = target:FindFirstChildWhichIsA("Animator", true)
	if not animator then
		return
	end
	local endsAt = os.clock() + duration
	for _, track in animator:GetPlayingAnimationTracks() do
		local f = frozen[track]
		if f then
			f.endsAt = math.max(f.endsAt, endsAt)
		else
			frozen[track] = { speed = track.Speed, endsAt = endsAt }
			track:AdjustSpeed(0)
		end
	end
	task.delay(duration, function()
		local now = os.clock()
		for track, f in frozen do
			if f.endsAt <= now + 0.001 then
				frozen[track] = nil
				if track.IsPlaying then
					track:AdjustSpeed(f.speed)
				end
			end
		end
	end)
end

Effects.hitStop = hitStop

------------------------------------------------------------------------------------------- Preloading and stats
--- Loads the textures of these effects (all when nil) before they're first needed: no pop-in on the first
--- hit. Yields; call it from a loading screen.
function Effects.preload(names: { string }?)
	local r = rootFolder()
	if not r then
		return
	end
	local items: { Instance } = {}
	local wanted: { [string]: boolean }? = nil
	if names then
		local set: { [string]: boolean } = {}
		for _, n in names do
			set[n] = true
		end
		wanted = set
	end
	for _, tpl in r:GetChildren() do
		if wanted and not wanted[tpl.Name] then
			continue
		end
		if tpl:IsA("Trail") or tpl:IsA("Beam") then
			table.insert(items, tpl)
		end
		for _, d in tpl:GetDescendants() do
			if d:IsA("ParticleEmitter") then
				table.insert(items, d)
			end
		end
	end
	pcall(function()
		ContentProvider:PreloadAsync(items)
	end)
end

--- What runs now: effects, frame jobs, particles still alive (from what was emitted), parts and lights
--- in use, Highlights, the quality level. vfx_play reports it; a debug overlay can show it.
function Effects.stats(): { effects: number, jobs: number, particles: number, parts: number, lights: number, highlights: number, quality: Quality }
	local particles = 0
	local now = os.clock()
	for _, batch in live do
		if batch.untilAt >= now then
			particles += batch.count
		end
	end
	return { effects = effectsLive, jobs = #jobs, particles = particles, parts = partsOut, lights = lightsLive, highlights = highlightsLive, quality = Effects.quality() }
end

------------------------------------------------------------------------------------------- Client listener
local listening = false

--- Called by the generated client script: plays what the server relays, and starts the weather.
function Effects.listen()
	if listening or not RunService:IsClient() then
		return
	end
	listening = true
	task.spawn(function()
		local r = ReplicatedStorage:WaitForChild("ShurikenEffects")
		local remote = r:WaitForChild("Remote") :: RemoteEvent
		remote.OnClientEvent:Connect(function(cue: string, a: any, b: any, opts: any)
			if cue == "__shake" then
				shakeCamera(num(a, 1.5), num(b, 0.25))
			elseif cue == "__projectile" then
				Effects.projectile(a)
			elseif cue == "__lightning" then
				Effects.lightning(a, b, opts)
			elseif cue == "__chain" then
				Effects.chain(a, opts, b)
			elseif cue == "__telegraph" then
				Effects.telegraph(a, opts)
			elseif cue == "__flash" then
				Effects.flash(a, opts)
			elseif cue == "__hitstop" then
				Effects.hitStop(a, b)
			elseif cue == "__screen" then
				local Screen = sibling("ShurikenScreenFX")
				if Screen and Screen.cue then
					Screen.cue(a, b)
				end
			elseif cue == "__cutscene" then
				local Cutscene = sibling("ShurikenCutscene")
				if Cutscene and Cutscene.play then
					Cutscene.play(a, b)
				end
			else
				local handle = Effects.play(cue, a, opts)
				local r = rootFolder()
				local tpl = r and r:FindFirstChild(cue)
				if handle and tpl and tpl:GetAttribute("Kind") == "persistent" then
					-- Started by the server: nobody here holds the handle, so it ends by itself.
					task.delay(if typeof(opts) == "table" then num(opts.seconds, 5) else 5, handle.stop)
				end
			end
		end)
	end)
	local Weather = sibling("ShurikenWeather")
	if Weather and Weather.start then
		task.spawn(Weather.start)
	end
end

--- Server: starts a cutscene (ShurikenCutscene.play does this for you) for opts.players, or everyone.
function Effects.relayCutscene(nameOrData: any, opts: any)
	if relaying() then
		local o = if typeof(opts) == "table" then table.clone(opts) else nil
		if o then
			o.onEnded = nil
		end
		relay("__cutscene", nameOrData, nil, o)
	end
end

--- Relays a screen cue (ShurikenScreenFX.cue) from the server to players: a kill banner for the killer.
function Effects.screen(fx: string, params: any, opts: Options?)
	if relaying() then
		relay("__screen", fx, params, opts)
		return
	end
	local Screen = sibling("ShurikenScreenFX")
	if Screen and Screen.cue then
		Screen.cue(fx, params)
	end
end

return Effects
`;
